        (32,'injury',0,1,0,None,0,None,0),(33,'extreme-panic',0,1,0,'unmodified-will-after-authored-reaction',0,None,0),
        (34,'trait',0,1,0,None,-15,'delusion',0),(35,'trait',0,1,0,None,-15,'mental-disadvantage',0),
