        first = Session(bundle)
        try:
            first.action(2080,0); first.action(2080,5)
            if stage >= 1:
                first.action(2080,20)
            if stage >= 2:
                first.action(2080,3)
            if stage >= 3:
                first.action(2080,23)
            saved = (computer_state(first),terminal_state(first))
            first.command(f':save {path}')
        finally:
            first.close()
        second = Session(bundle)
