def test_neurological_agent(Session, bundle, out):
    def state(s):
        s.action(2285, 485)
        return last(s, 'test.neurological')
    for invalid in (481, 483):
        s = Session(bundle)
        try:
            for code in (480, invalid, 260):
                s.action(2285, code)
            assert state(s) == [0, 0, 0, 0, 0, 0, 0, 0]
        finally:
            s.close()
    path = out / 'expanded-neurological.zsave'
    s = Session(bundle)
    try:
        for code in (480, 324, 265, 260, 261, 263):
            s.action(2285, code)
        assert last(s, 'test.poison-catalogue') == [6, 20, 0, 0, 60, 6, 2, 1, -6]
        assert state(s) == [1, 6, 0, 0, 0, 0, 0, 0]
        s.action(2285, 262)
        s.command('undo')
        assert state(s) == [1, 6, 0, 0, 0, 0, 0, 0]
        for code in (262, 262):
            s.action(2285, code)
        assert state(s) == [1, 5, 8, 1, 0, 1, 0, 5]
        s.command(f':save {path}\n@2286')
    finally:
        s.close()
    s = Session(bundle)
    try:
        s.command(f':restore {path}\n@2286')
        for count in range(2, 7):
            s.action(2285, 333)
            assert state(s) == [1, 6-count, 8*count, int(count == 2), 0, 1, 60*(count-1), 5*count]
    finally:
        s.close()
    s = Session(bundle)
    try:
        for code in (480, 482, 265, 260, 262):
            s.action(2285, code)
        assert state(s) == [1, 5, 8, 0, 1, 1, 0, 5]
        for code in (4, 486, 486):
            s.action(2285, code)
        assert state(s) == [1, 5, 8, 0, 0, 1, 60, 6]
    finally:
        s.close()

    s = Session(bundle)
    try:
        for code in (480, 31, 260, 262):
            s.action(2285, code)
        assert state(s) == [1, 0, 0, 0, 0, 0, 0, 3]
    finally:
        s.close()

    # One exposure owns toxic cycles; its agony episode independently owns FP.
    s = Session(bundle)
    try:
        for code in (480, 487, 265, 260, 261, 263, 489):
            s.action(2285, code)
        assert last(s, 'test.neurological-agony') == [0, 0, 0, 0, 0, 0]
        for code in (262, 262, 489):
            s.action(2285, code)
        assert last(s, 'test.neurological-agony') == [1, 1, 8, 1, 0, 5]
        for code in (333, 489):
            s.action(2285, code)
        assert last(s, 'test.neurological-agony') == [1, 1, 16, 1, 60, 10]
        # Both systems have a deadline at sixty: toxic resolution does not pay FP.
        for code in (6, 489):
            s.action(2285, code)
        assert last(s, 'test.neurological-agony') == [1, 1, 16, 1, 60, 10]
        for code in (488, 488, 6, 489):
            s.action(2285, code)
        assert last(s, 'test.neurological-agony') == [0, 2, 16, 2, 61, 10]
    finally:
        s.close()


