def test_shared_support_loss(Session, bundle, out):
    def state(s):
        s.action(2285, 802)
        return last(s, 'test.shared-support-loss')
    path = out / 'expanded-shared-support-loss.zsave'
    s = Session(bundle)
    try:
        for code in (781,803):
            s.action(2285, code)
        assert state(s) == [0,0,0,4]
        # Recovery during lowering does not settle the physical support loss.
        # The failed action must roll back its clock, event and load transfer.
        s.action(2285, 804)
        assert state(s) == [0,0,0,4]
        s.action(2285, 783)
        assert last(s, 'test.shared-carry') == [2000,4000,1,0,1,1,1,4,0]
        s.action(2285, 800)
        s.command('undo')
        assert state(s) == [0,0,0,4]
        for code in (800,800,801):
            s.action(2285, code)
        assert last(s, 'test.shared-support-clock') == ['shared-support-loss-unresolved',4]
        assert state(s) == [1,1,1,4]
        s.command(f':save {path}\n@2286')
    finally:
        s.close()
    s = Session(bundle)
    try:
        s.command(f':restore {path}\n@2286')
        for code in (795,801):
            s.action(2285, code)
        assert state(s) == [1,1,0,4]
        assert last(s, 'test.shared-support-clock') == ['shared-support-loss-unresolved',4]
        for code in (791,801):
            s.action(2285, code)
        assert last(s, 'test.shared-support-clock') == ['advanced',5]
        assert state(s) == [1,0,0,5]
    finally:
        s.close()


