def test_climb_assessment(Session, bundle):
    # Independently transcribed B349 rates in feet/rungs per minute.
    rows = [(None,180,60,'rungs'), (None,120,60,'rungs'),
            (5,60,20,'feet'), (0,30,10,'feet'), (-3,12,4,'feet'),
            (-3,6,2,'feet'), (-2,60,20,'feet'), (-1,120,30,'feet'),
            (-1,720,720,'feet')]
    s = Session(bundle)
    try:
        for index, (modifier, fast, regular, unit) in enumerate(rows, 1):
            for combat, rate in ((0,regular), (1,fast)):
                s.action(2292,index,rate,2,combat,3)
                assert last(s, 'test.climb-assessment') == [
                    unit,rate,60,60,None if modifier is None else modifier-2,
                    0 if modifier is None else 1,6 if combat else 3,
                    'move' if combat else None,0,0]
        # Exact fractional speed: a building climb takes 30 seconds per foot.
        for distance, seconds, checks in ((9,270,1),(10,300,2),(11,330,2)):
            s.action(2292,6,distance,0,0,0)
            assert last(s, 'test.climb-assessment') == ['feet',2,60,seconds,-3,checks,0,None,0,0]
        # Round only the final duration; ladder climbing still costs combat effort.
        s.action(2292,1,1,4,1,0)
        assert last(s, 'test.climb-assessment') == ['rungs',180,60,1,None,0,1,'move',0,0]
        s.action(2292,9,13,0,0,0)
        assert last(s, 'test.climb-assessment') == ['feet',720,60,2,-1,1,0,None,0,0]
    finally:
        s.close()


def test_climb_fall_assessment(Session, bundle):
    s = Session(bundle)
    try:
        cases = [
            ((12,10,30,1,6), [1,None,0,0,0,0,0,0]),
            ((12,14,30,1,6), [0,None,1,1,6,1,0,0]),
            ((12,18,30,1,6), [0,'failure',1,0,30,1,0,0]),
            ((12,14,30,0,0), [0,None,1,0,30,1,0,0]),
            ((12,14,3,1,6), [0,None,1,0,3,1,0,0]),
            ((12,14,30,1,0), [0,None,1,1,0,1,0,0]),
        ]
        for args, expected in cases:
            s.action(2293,*args)
            assert last(s, 'test.climb-fall') == expected
        # Printed B431 upper endpoints, grouped independently by table columns.
        columns = [
            [(1,5),(2,7),(3,8),(4,9),(5,10),(6,11),(7,12),(8,13),(9,14),(11,15),(12,16)],
            [(14,17),(15,18),(17,19),(19,20),(21,21),(23,22),(25,23),(27,24),(29,25),(32,26),(34,27)],
            [(37,28),(39,29),(42,30),(45,31),(48,32),(51,33),(54,34),(57,35),(61,36),(64,37),(67,38)],
            [(71,39),(75,40),(79,41),(82,42),(86,43),(90,44),(95,45),(99,46),(103,47),(108,48),(112,49)],
        ]
        previous = 0
        for column in columns:
            for upper, velocity in column:
                for yards in range(previous+1,upper+1):
                    s.action(2294,yards)
                    assert last(s, 'test.fall-velocity') == [velocity,0,0]
                previous = upper
        s.action(2294,0)
        assert last(s, 'test.fall-velocity') == [0,0,0]
    finally:
        s.close()


def test_collision_assessment(Session, bundle):
    s = Session(bundle)
    try:
        # B430 fractional-die thresholds and ordinary rounding, without RNG.
        for speed, dice, adds in [(0,0,0),(1,1,-3),(25,1,-3),(26,1,-2),
                                   (50,1,-2),(51,1,-1),(99,1,-1),(100,1,0),
                                   (149,1,0),(150,2,0),(249,2,0),(250,3,0)]:
            s.action(2292,1,speed,0)
            assert last(s, 'test.collision') == [1,speed,dice,adds,'cr',0,0]
        # B431 worked example: 10 HP at 19 yards/second against a hard surface.
        s.action(2292,10,19,1)
        assert last(s, 'test.collision') == [20,19,4,0,'cr',0,0]
        s.action(2292,10,19,0)
        assert last(s, 'test.collision') == [10,19,2,0,'cr',0,0]
        s.action(2292,10,0,1)
        assert last(s, 'test.collision') == [20,0,0,0,'cr',0,0]
    finally:
        s.close()


