def test_template_taboo(Session, bundle, out):
    path = out / 'expanded-template-taboo.zsave'
    for setup, invalid in ((5810, 5817), (5811, 5818)):
        s = Session(bundle)
        try:
            for code in (5800, setup, 5816):
                s.action(2285, code)
            assert last(s, 'test.taboo-secondary') == ['blocked', 'taboo-attribute', 40, 10, 10, 10, 100]
            for code in (5814, 5816):
                s.action(2285, code)
            assert last(s, 'test.taboo-secondary') == ['blocked', 'taboo-attribute', 60, 10, 10, 10, 100]
            for code in (5815, 5816):
                s.action(2285, code)
            assert last(s, 'test.taboo-secondary') == ['ready', None, 80, 10, 10, 10, 100]
            for code in (setup, 5812, 5816):
                s.action(2285, code)
            assert last(s, 'test.taboo-secondary') == ['blocked', 'taboo-attribute', 10, 10, 10, 10, 100]
            for code in (5813, 5816):
                s.action(2285, code)
            assert last(s, 'test.taboo-secondary') == ['ready', None, 5, 10, 10, 10, 100]
            for code in (5819, 5816):
                s.action(2285, code)
            expected_will, expected_perception = (11, 10) if setup == 5810 else (10, 11)
            assert last(s, 'test.taboo-secondary') == [
                'blocked', 'taboo-attribute', 20, 10, expected_will, expected_perception, 100]
            for code in (invalid, 5806):
                s.action(2285, code)
            assert last(s, 'test.taboo-error') == ['taboo-attribute']
        finally:
            s.close()
    for change, reason in ((5803, 'taboo-attribute'), (5804, 'taboo-trait'), (5805, 'taboo-skill')):
        s = Session(bundle)
        try:
            for code in (5800, change, 5806):
                s.action(2285, code)
            assert last(s, 'test.taboo-error') == [reason]
        finally:
            s.close()
    s = Session(bundle)
    try:
        for code in (5800, 5801):
            s.action(2285, code)
        assert last(s, 'test.taboo') == [6, 'taboo-skill', 0, 'taboo-trait', 100, 0, 0]
        s.action(2285, 5803)
        s.command('undo')
        for code in (5802, 5801):
            s.action(2285, code)
        assert last(s, 'test.taboo') == [6, 'taboo-skill', 0, 'taboo-attribute', 100, 0, 0]
        s.command(f':save {path}\n@2286')
    finally:
        s.close()
    s = Session(bundle)
    try:
        s.command(f':restore {path}\n@2286')
        s.action(2285, 5801)
        assert last(s, 'test.taboo') == [6, 'taboo-skill', 0, 'taboo-attribute', 100, 0, 0]
    finally:
        s.close()


def test_ancestry_scores(Session, bundle, out):
    path = out / 'expanded-ancestry-scores.zsave'
    for setup in (5920, 5921, 5922, 5923):
        s = Session(bundle)
        try:
            for code in (setup, 5905):
                s.action(2285, code)
            if setup == 5923:
                assert last(s, 'test.ancestry-before-validation') == ['point-budget']
                expected_final = [10, -10, 10, 11, 10, 10, 10, 11, 20, 1, 0, 0]
            else:
                assert last(s, 'test.ancestry-before-validation') == ['secondary-limit']
                expected_final = [20, 0, 0, 10, 10, 10, 10, 20, 20, 1, 0, 0]
            assert last(s, 'test.ancestry-scores') == expected_final
            for code in (5924, 5905):
                s.action(2285, code)
            assert last(s, 'test.ancestry-score-error') == ['secondary-limit']
            assert last(s, 'test.ancestry-scores') == expected_final
        finally:
            s.close()
    for setup in (5915, 5916, 5917):
        s = Session(bundle)
        try:
            s.action(2285, setup)
            assert last(s, 'test.ancestry-score-error') == ['secondary-limit']
        finally:
            s.close()
    s = Session(bundle)
    try:
        for code in (5914, 5905):
            s.action(2285, code)
        assert last(s, 'test.ancestry-score-error') == ['accepted']
        assert last(s, 'test.ancestry-scores') == [130, 0, 0, 10, 10, 10, 10, 20, 32, 1, 0, 0]
        for code in (5918, 5907):
            s.action(2285, code)
        assert last(s, 'test.ancestry-score-error') == ['ancestry-score-binding']
    finally:
        s.close()
    expected = {
        5900: [82, 0, 0, 17, 10, 10, 10, 23, 20, 1, 0, 0],
        5901: [115, -15, 15, 10, 14, 10, 13, 10, 28, 1, 0, 0],
        5902: [150, -30, 20, 19, 10, 13, 10, 19, 20, 1, 0, 0],
        5903: [58, 0, 0, 15, 10, 10, 10, 19, 20, 2, 0, 0],
        5904: [0, 0, 0, 10, 10, 10, 10, 10, 20, 0, 0, 0],
        5911: [-10, -10, 10, 9, 10, 10, 10, 9, 20, 1, 0, 0],
    }
    s = Session(bundle)
    try:
        for setup, values in expected.items():
            s.action(2285, setup)
            s.action(2285, 5905)
            assert last(s, 'test.ancestry-scores') == values
        for code in (5902, 5908, 5907):
            s.action(2285, code)
        assert last(s, 'test.ancestry-score-error') == ['point-budget']
        for code in (5902, 5906, 5907):
            s.action(2285, code)
        assert last(s, 'test.ancestry-score-error') == ['ancestry-score-binding']
        s.action(2285, 5910)
        assert last(s, 'test.ancestry-score-error') == ['accepted']
        s.action(2285, 5905)
        assert last(s, 'test.ancestry-scores') == expected[5911]
        s.action(2285, 5902)
        s.action(2285, 5909)
        s.command('undo')
        s.action(2285, 5905)
        assert last(s, 'test.ancestry-scores') == expected[5902]
        s.action(2285, 5909)
        assert last(s, 'test.ancestry-growth') == ['resolved', 10, 90]
        s.action(2285, 5905)
        assert last(s, 'test.ancestry-scores') == [160, -20, 20, 20, 10, 13, 10, 20, 20, 1, 0, 0]
        s.command(f':save {path}\n@2286')
    finally:
        s.close()
    s = Session(bundle)
    try:
        s.command(f':restore {path}\n@2286')
        s.action(2285, 5905)
        assert last(s, 'test.ancestry-scores') == [160, -20, 20, 20, 10, 13, 10, 20, 20, 1, 0, 0]
    finally:
        s.close()


