        assert state(s) == first
        s.action(1680,29609); assert last(s,'test.shadow-round-outcome') == [1,0,0,0,0,0]
        s.action(1680,29610); assert state(s) == first
        s.action(1680,29609); assert last(s,'test.shadow-round-outcome') == [1,0,0,0,0,0]
        s.action(1680,29603); assert state(s) == first
